<?php require 'config.php';if(empty($_SESSION['user_id']))go('login.php');$s=$pdo->prepare('SELECT status,COUNT(*) c FROM complaints WHERE user_id=? GROUP BY status');$s->execute([$_SESSION['user_id']]);$c=['Pending'=>0,'In Progress'=>0,'Resolved'=>0,'Total'=>0];foreach($s as $r){$c[$r['status']]=$r['c'];$c['Total']+=$r['c'];}$s=$pdo->prepare('SELECT * FROM complaints WHERE user_id=? ORDER BY id DESC LIMIT 5');$s->execute([$_SESSION['user_id']]);$rows=$s->fetchAll();$title='Dashboard';require 'partials/top.php';?><section class="glass hero"><span class="eyebrow">WORKPLACE SUPPORT</span><h1>Welcome to NML ICH Complaint Portal</h1><p>Report · Track · Resolve · Build a better workplace</p><a class="button" href="new_complaint.php">＋ Register Complaint</a></section><section class="stats"><div class="glass stat"><small>Total Complaints</small><strong><?=$c['Total']?></strong></div><div class="glass stat"><small>In Progress</small><strong><?=$c['In Progress']?></strong></div><div class="glass stat"><small>Resolved</small><strong><?=$c['Resolved']?></strong></div><div class="glass stat"><small>Pending</small><strong><?=$c['Pending']?></strong></div></section><section class="glass panel"><h3>Recent Complaints</h3><?php if(!$rows):?><p>No complaints yet. Use Register Complaint to submit an issue.</p><?php else:?><div class="tablewrap"><table><tr><th>ID</th><th>Title</th><th>Department</th><th>Status</th><th>Date</th></tr><?php foreach($rows as $r):?><tr><td><?=e($r['complaint_code'])?></td><td><?=e($r['title'])?></td><td><?=e($r['department'])?></td><td><span class="status"><?=e($r['status'])?></span></td><td><?=e(date('d M Y',strtotime($r['created_at'])))?></td></tr><?php endforeach;?></table></div><?php endif;?></section><?php require 'partials/bottom.php';?>